from boltons.setutils import IndexedSet

def test_negative_index_wrap():
    x = IndexedSet(range(9))
    print(f"Set length: {len(x)}")
    try:
        print(f"x[-10]: {x[-10]}")
    except IndexError as e:
        print(f"x[-10] raised IndexError: {e}")

def test_pop_negative_index_wrap():
    x = IndexedSet(range(9))
    print(f"Set length: {len(x)}")
    try:
        popped = x.pop(-15)
        print(f"x.pop(-15) popped: {popped}")
        print(f"Set after pop: {x}")
    except IndexError as e:
        print(f"x.pop(-15) raised IndexError: {e}")

if __name__ == "__main__":
    test_negative_index_wrap()
    test_pop_negative_index_wrap()

